from pathlib import Path
prog='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def inside(r, c):
        return 0 <= r < h and 0 <= c < w

    # Matching diagonal pairs are extended away from the local motif.
    # An occupied continuation blocks a ray; when both continuations are
    # clear, choose the nearer edge. Do not extend a pair already at an edge.
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r][c] == grid[r + 1][c2] and grid[r][c] != bg:
                    pairs.append((r, c, r + 1, c2, grid[r][c], dc))

    for r1, c1, r2, c2, color, dc in pairs:
        # Rays before first cell and after second cell along pair slope.
        starts = [(r1 - 1, c1 - dc, -1, -dc), (r2 + 1, c2 + dc, 1, dc)]
        states = []
        lengths = []
        for sr, sc, dr, dcol in starts:
            if not inside(sr, sc):
                states.append('edge'); lengths.append(0); continue
            if grid[sr][sc] != bg:
                states.append('blocked'); lengths.append(0); continue
            states.append('clear')
            rr, cc, n = sr, sc, 0
            while inside(rr, cc) and grid[rr][cc] == bg:
                n += 1
                rr += dr; cc += dcol
            lengths.append(n)
        if states == ['clear', 'clear']:
            dirs = [0 if lengths[0] <= lengths[1] else 1]
        elif states[0] == 'blocked' and states[1] == 'clear':
            dirs = [1]
        elif states[1] == 'blocked' and states[0] == 'clear':
            dirs = [0]
        else:
            dirs = []
        for i in dirs:
            rr, cc, dr, dcol = starts[i]
            while inside(rr, cc) and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += dr; cc += dcol
    return out
'''
